"""Parity with the TypeScript engine, using fixtures generated by scripts/fixtures.ts."""

import json
from pathlib import Path

import pytest

from orsolver.engine import PIECES, SPAWN, H, W, hex_board, points, reachable, drops
from orsolver.evaluate import analyze

FX = json.loads((Path(__file__).parent / "fixtures" / "engine.json").read_text())
BOARDS = {name: tuple(int(row[::-1], 2) for row in rows) for name, rows in FX["boards"].items()}


@pytest.mark.parametrize("case", FX["cases"], ids=lambda c: f"{c['name']}-{c['piece']}-{'adv' if c['advanced'] else 'basic'}")
def test_reachable_lock_sets_match_ts(case):
    b = BOARDS[case["name"]]
    got = {(hex_board(lk.board), lk.spin, lk.lines) for lk in reachable(b, case["piece"], SPAWN[case["piece"]], case["advanced"])}
    want = {(lk["board"], lk["spin"], lk["lines"]) for lk in case["locks"]}
    assert got == want


@pytest.mark.parametrize("f", FX["features"], ids=lambda f: f["name"])
def test_features_match_ts(f):
    a = analyze(BOARDS[f["name"]])
    assert list(a.heights) == f["heights"]
    assert (a.agg_height, a.max_height, a.bumpiness, a.holes, a.rows_with_holes, a.row_trans, a.col_trans, a.wells) == (
        f["aggHeight"], f["maxHeight"], f["bumpiness"], f["holes"], f["rowsWithHoles"], f["rowTrans"], f["colTrans"], f["wells"])


def test_points_match_ts():
    for p in FX["points"]:
        assert points(p["lines"], p["spin"], p["level"]) == p["points"]


def test_fast_drops_equal_basic_reachability_from_spawn():
    for name, b in BOARDS.items():
        if max(analyze(b).heights) > 14:
            continue
        for piece in PIECES:
            assert {d[0] for d in drops(b, piece)} == {lk.board for lk in reachable(b, piece, SPAWN[piece], False)}, (name, piece)
